import {createClientTrial} from './client-trial-ui.mjs';
import {opportunities,agents,paths,deliverables,costKeys,optionTotals,score,readyForTrial,blankPlan,importPlan} from './project-model.mjs';
export function createProject({esc,toast,render}){
 let plan=blankPlan(),dirty=false;
 const clientTrial=createClientTrial({getData:()=>plan.clientTrial,changed:()=>{dirty=true;},esc,toast});
 const routes=['home','discovery','opportunities','reviews','options','roadmap'];
 const titles={home:'Workspace overview',discovery:'Team needs & tool usage',opportunities:'Opportunity register',reviews:'Agent reviews & controlled trials',options:'Compare the four paths',roadmap:'Roadmap & ownership'};
 const summaries={home:'Data quality, workflows and continuous improvement for Phillip Riley teams.',discovery:'Keep track of how teams use their tools, where work slows down and what needs to improve.',opportunities:'15 hypotheses to investigate. Scores and evidence are intentionally blank until staff help validate them.',reviews:'Review AI quality and usefulness regularly, and test proposed changes on approved samples.',options:'Compare the same agreed use case across all four options before choosing a solution.',roadmap:'Maintain a rolling plan for improvements, responsibilities, training and ongoing support.'};
 const value=(section,id,key)=>plan[section][id]?.[key]||'';
 function field(section,id,key,label,options){
  const v=value(section,id,key),attrs=`data-project-section="${esc(section)}" data-project-id="${esc(id)}" data-project-key="${esc(key)}"`;
  return `<label>${esc(label)}${options?`<select ${attrs}><option value="">Not recorded</option>${options.map(o=>`<option ${v===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:costKeys.includes(key)?`<input ${attrs} type="number" min="0" max="100000000" step="any" placeholder="Unknown" value="${esc(v)}">`:`<textarea ${attrs} maxlength="4000" rows="2" placeholder="Not yet recorded">${esc(v)}</textarea>`}</label>`;
 }
 const fields=(s,id,list)=>list.map(([k,label,options])=>field(s,id,k,label,options)).join('');
 const link=(route,label)=>`<a class="button secondary" href="#${route}">${esc(label)}</a>`;
 function home(){return `<section class="project-hero"><p class="eyebrow">PEOPLE · PROCESS · DATA · IMPROVEMENT</p><h2>Better information.<br>Less repeated work.</h2><p>A workspace for Phillip Riley teams to improve data quality, coordinate workflows, review AI tools and make informed decisions about cost and service. Keep ownership, evidence and next actions clear as the business evolves.</p><div class="actions">${link('queue','Review enrichment')}${link('platforms','Find a tool or workflow')}</div></section><section class="panel"><h2>What do you need to do?</h2><div class="staff-start-grid"><a href="#queue"><strong>Review information</strong><span>Check proposed field changes against their sources and record a review decision.</span></a><a href="#workflow"><strong>Follow a process</strong><span>Find recruitment stages, human checks and the next handoff.</span></a><a href="#opportunities"><strong>Assess an improvement</strong><span>Compare recurring problems, expected value, evidence and effort.</span></a><a href="#reviews"><strong>Review an AI tool</strong><span>Check quality, staff feedback and trial results before changing how the team works.</span></a></div></section><div class="two-col"><section class="panel"><h2>Workspace availability</h2><p>Browse tools and processes, compare costs and complete downloadable planning worksheets now. Enrichment and case workflows currently use synthetic examples.</p><p>Staff sign-in, shared records and live connections still need setup. Measured savings and service improvements will be recorded when evidence is available.</p></section><section class="panel"><h2>Keep improvements accountable</h2><ol><li>Record the issue, affected workflow and responsible team.</li><li>Review existing tools and test an agreed change.</li><li>Compare results and costs, then maintain, improve or retire the approach.</li></ol></section></div><section class="panel"><h2>Manage continuous improvement</h2><p>Keep these work areas current as tools, processes and team needs change. Each area connects evidence to a practical next action.</p><div class="project-deliverables">${deliverables.map(([name,status,next,route],i)=>`<a href="#${route}"><span class="project-number">${i+1}</span><div><h3>${esc(name)}</h3><span class="pill">${esc(status)}</span><p>${esc(next)}</p></div><span aria-hidden="true">↗</span></a>`).join('')}</div></section>`;}
 function discovery(){return `<div class="notice">Use <a href="#platforms">Platform hub</a> and <a href="#workflow">Process map</a> as the starting point. Do not repeat questions already answered there. Capture sanitised observations and references to evidence held in approved company systems.</div>${['Recruitment','Operations','Sales','Finance','Marketing','Shared services'].map(id=>`<details class="panel"><summary>${id}</summary><div class="project-form">${fields('discovery',id,[['owner','Tool / process owner (role)'],['paid','What is included in current licences?'],['configured','What is configured or connected?'],['used','What is actually used, and how often?'],['gap','Where does time or quality get lost?'],['evidence','Sanitised observation / approved evidence reference'],['next','Next question, owner and date']])}</div></details>`).join('')}`;}
 function register(){const sorted=[...opportunities].sort((a,b)=>(score(plan.opportunities[b.id]||{})??-1)-(score(plan.opportunities[a.id]||{})??-1));return `<div class="notice"><strong>Proposed scoring, for discussion:</strong> impact + frequency + feasibility, each 1–5; maximum 15. Higher means more valuable, more frequent and easier to test. Equal weights are a starting assumption, not PRG policy. A score does not establish permission or prove benefit. Unknown ratings remain unranked; risks can override the score.</div><div class="actions"><button data-project="refresh">Update ranking</button><span>${opportunities.filter(o=>readyForTrial(plan.opportunities[o.id]||{})).length} ideas have a validated label, evidence reference, owner and all ratings in this worksheet. This is not trial approval.</span></div>${sorted.map(o=>{const x=plan.opportunities[o.id]||{},n=score(x);return `<details class="panel"><summary><span class="project-score">${n===null?'—':`${n}/15`}</span> ${esc(o.id)} · ${esc(o.name)} <span class="pill">${esc(x.status||'Hypothesis')}</span></summary><p>${esc(o.team)} · ${esc(o.hypothesis)}</p><div class="project-form">${fields('opportunities',o.id,[['status','Evidence status',['Hypothesis','Investigating','Validated','Deferred']],['impact','Impact: 1 low → 5 high',['1','2','3','4','5']],['frequency','Frequency: 1 rare → 5 frequent',['1','2','3','4','5']],['feasibility','Feasibility: 1 difficult → 5 easy',['1','2','3','4','5']],['owner','Accountable role'],['evidence','Observed problem, baseline and evidence reference'],['risk','Data, quality, adoption or commercial risk'],['next','Next validation step']])}</div></details>`;}).join('')}`;}
 function reviews(){return `${clientTrial.view()}<section class="panel"><h2>Review existing agents first</h2><p>Start with the three existing AI use cases below. Confirm their current configuration, quality and adoption with the responsible teams. Record approved test examples, errors, staff feedback and a keep / improve / retire recommendation.</p></section>${agents.map(id=>`<details class="panel"><summary>${esc(id)}</summary><div class="project-form">${fields('agents',id,[['owner','Owner and users (roles)'],['purpose','Current task and baseline workflow'],['access','Approved access and permitted information'],['evidence','Test cases and evidence references'],['quality','Accuracy, rework, time and staff feedback'],['decision','Proposed decision',['Keep','Improve','Retire','More evidence needed']],['next','Change to test next']])}</div></details>`).join('')}<section class="panel"><h2>Plan and review controlled trials</h2><p>Agree the cohort and thresholds before testing. Include review and correction time in the assisted result. Report accuracy with its denominator and serious errors separately. Technical software tests are not business trial results.</p><div class="actions">${link('queue','Open synthetic enrichment rehearsal')}${link('pilot','Calculate pilot measurements')}</div></section>${['Trial 1','Trial 2','Trial 3'].map(id=>`<details class="panel"><summary>${id==='Trial 1'?'Trial 1 · Client prioritisation plan & measurements':id} · ${esc(value('trials',id,'outcome')||'Not assessed')}</summary><div class="project-form">${fields('trials',id,[['scope','Opportunity ID, task and comparison'],['owner','Trial owner and human reviewer'],['approval','Approval reference and permitted data / tools'],['cohort','Sample, exclusions and measurement method'],['baseline','Manual baseline: time, volume and error rate'],['assisted','Assisted time including review and corrections'],['quality','Agreed quality threshold and observed counts'],['cost','Trial cost including staff effort'],['stop','Stop conditions and escalation owner'],['evidence','Results and staff feedback references'],['outcome','Review outcome',['Not run','In progress','Proceed recommendation','Revise and retest','Stop recommendation']]])}</div></details>`).join('')}<div class="notice warning">Worksheet notes do not grant approval. Use synthetic examples in the public prototype. Any actual trial requires approved tools and data; retain human control of contact, hiring, compliance and live record changes.</div>`;}
 function optionsPage(){return `<section class="panel"><h2>Cost the same scope, in AUD</h2><p>Enter incremental costs for each path. Blank means unknown; use 0 only where confirmed. Setup and initial training are one-off; subscriptions, support and usage are annual. Include recurring training in annual support. Use a consistent GST basis and record the quote date and assumptions.</p><p>Three-year cost assumes unchanged annual costs and no discounting. Record renewal changes or exclusions in the basis. Existing licence spend belongs in the baseline; licence cancellation is a cash saving only when verified and achievable.</p></section><div class="project-options">${paths.map((id,i)=>{const totals=optionTotals(plan.options[id]||{}),money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0}).format(n);return `<section class="panel"><h2>${i+1}. ${esc(id)}</h2><div class="project-form">${fields('options',id,[['setup','One-off setup / implementation'],['training','One-off staff training'],['subscription','Annual subscription'],['support','Annual support / maintenance'],['usage','Annual usage / provider costs'],['basis','Quote / licence evidence, scope, GST and assumptions'],['benefit','Expected benefit and evidence; separate cash from capacity'],['risk','Quality, security, lock-in and adoption risks'],['resources','People, integrations and support required']])}</div><p class="project-total">Year 1: ${totals?money(totals.year1):'Unknown'}<br>Three years total: ${totals?money(totals.year3):'Unknown'}</p></section>`;}).join('')}</div><button data-project="refresh">Calculate comparison</button><section class="panel"><h2>Is a tailored PRG solution worth investigating?</h2><p>The existence of this prototype is not evidence that a custom build is the best option. Compare fit, ongoing ownership and total cost against the first three paths.</p><div class="project-form">${fields('recommendation','Decision',[['choice','Proposed path',['Existing tools','General AI platform','Specialist software','Tailored solution','More evidence needed']],['reason','Why this option best fits the agreed problem'],['unknowns','Evidence gaps and conditions'],['next','Smallest next step and decision owner']])}</div><p>Time released is capacity, not automatically payroll savings or revenue. Use the <a href="#costs">existing benefit calculator</a> for an explicitly labelled scenario; replace assumptions with observed measurements.</p></section>`;}
 function roadmap(){const phases=[['First 90 days','Validate priority problems, review existing AI and test agreed improvements before adoption.'],['Months 3–6','If approved, implement the selected option with a named owner, staff training and monitoring.'],['Months 6–12','Review sustained results, adoption and costs before expanding or retiring tools.']];return `<div class="notice">Use this rolling 12-month roadmap to agree priorities, owners and review points. Revisit it as results and business needs change. Purchases and rollout require the relevant business approval.</div>${phases.map(([id,idea])=>`<section class="panel"><h2>${id}</h2><p>Proposed focus: ${idea}</p><div class="project-form">${fields('roadmap',id,[['owner','Accountable role'],['scope','Agreed outcomes and scope'],['dependencies','Dependencies, resources and approvals'],['gate','Evidence required to proceed / stop']])}</div></section>`).join('')}<section class="panel"><h2>Ownership, training & ongoing support</h2><ul><li>Keep the tool map, ranked ideas, agent reviews, trial evidence and assumptions together in the approved company location.</li><li>Document who owns each process, prompt, connection, cost and unresolved decision.</li><li>Validate the staff guide with users, demonstrate the chosen workflow and collect training feedback.</li><li>Present the problem, evidence, four options, recommendation, risks and next decision to management.</li></ul><p>Keep guidance current, train new users and review adoption with team owners. Record support responsibilities and revisit results after each change.</p>${link('guide','Open staff guide')}</section>`;}
 function view(route){return `<div class="page-heading"><div><p class="eyebrow">PHILLIP RILEY / TEAM WORKSPACE</p><h1>${titles[route]}</h1><p>${summaries[route]}</p></div></div><div class="project-tools"><div><strong>Working notes · this tab only</strong><small>Not saved to the server or shared with staff. Download to keep your work, including client assessments; import to continue. Use sanitised notes, not personal records or confidential documents.</small></div><button class="secondary" data-project="export">Download worksheet</button><label class="button secondary project-import">Import worksheet<input type="file" id="project-import" accept=".json,application/json"></label></div>${({home,discovery,opportunities:register,reviews,options:optionsPage,roadmap})[route]()}`;}
 document.addEventListener('input',e=>{const d=e.target.dataset;if(!d.projectSection)return;(plan[d.projectSection][d.projectId]??={})[d.projectKey]=e.target.value;dirty=true;});
 document.addEventListener('click',e=>{const action=e.target.closest('[data-project]')?.dataset.project;if(!action)return;if(action==='refresh')render();if(action==='export'){const blob=new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='prg-discovery-worksheet.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);dirty=false;toast('Worksheet downloaded. Keep it in an approved location; it has not been shared or submitted.');}});
 document.addEventListener('change',async e=>{if(e.target.id!=='project-import')return;try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw new Error('Use a worksheet smaller than 5 MB.');const next=importPlan(JSON.parse(await file.text()));if(dirty&&!window.confirm('Replace the current notes? Download them first if you need to keep them.'))return;plan=next;clientTrial.reset();dirty=false;render();toast('Worksheet opened in this tab. Evidence and approvals have not been independently verified.');}catch(err){toast(err.message);}finally{e.target.value='';}});
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 return {view,routes};
}
